// Package acknowledgements is the third-party software Hammock's apps ship,
// with each one's licence: Acknowledgements.json, generated by `just
// acknowledgements` (./gen). The Mac and iPhone apps bundle the same file
// (Settings ▸ About ▸ Acknowledgements); hmk shows it (`hmk
// acknowledgements`), and the Linux tarballs carry it as text.
package acknowledgements

import (
	_ "embed"
	"encoding/json"
	"runtime"
	"slices"
	"strconv"
	"strings"
)

//go:embed Acknowledgements.json
var raw []byte

// File is Acknowledgements.json.
type File struct {
	Components []Component `json:"components"`
}

// Component is one piece of third-party software, or a family of packages
// (CodeMirror's, golang.org/x's) listed together.
type Component struct {
	Name    string `json:"name"`
	Version string `json:"version,omitempty"`
	URL     string `json:"url,omitempty"`
	// License is SPDX ids, joined with " AND " when it has several.
	License string `json:"license"`
	// Apps it ships in: mac, ios, linux.
	Apps []string `json:"apps"`
	// Packages are a family's members (Name is the family's).
	Packages []Package `json:"packages,omitempty"`
	// Note says what Hammock uses it for, or which of a dual licence applies.
	Note string `json:"note,omitempty"`
	// Credits names a bundled file of further notices: "chromium", the
	// Chromium credits in the Mac app's browser host.
	Credits string `json:"credits,omitempty"`
	// Text is its licence files' full text.
	Text string `json:"text"`
}

// Package is one member of a family.
type Package struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

// All is every component, in every app, by name.
func All() []Component {
	var f File
	if err := json.Unmarshal(raw, &f); err != nil {
		panic("acknowledgements: " + err.Error())
	}
	return f.Components
}

// For is the components in one app: mac, ios or linux.
func For(app string) []Component {
	var out []Component
	for _, c := range All() {
		if slices.Contains(c.Apps, app) {
			out = append(out, c)
		}
	}
	return out
}

// ThisApp is the app hmk is part of here: the Mac app's on macOS, the
// Linux build's elsewhere.
func ThisApp() string {
	if runtime.GOOS == "darwin" {
		return "mac"
	}
	return "linux"
}

// Find is the components whose name (or a member's) matches q: exactly,
// else by prefix, else containing it, ignoring case.
func Find(cs []Component, q string) []Component {
	q = strings.ToLower(strings.TrimSpace(q))
	names := func(c Component) []string {
		n := []string{strings.ToLower(c.Name)}
		for _, p := range c.Packages {
			n = append(n, strings.ToLower(p.Name))
		}
		return n
	}
	for _, match := range []func(string) bool{
		func(n string) bool { return n == q },
		func(n string) bool { return strings.HasPrefix(n, q) },
		func(n string) bool { return strings.Contains(n, q) },
	} {
		var out []Component
		for _, c := range cs {
			if slices.ContainsFunc(names(c), match) {
				out = append(out, c)
			}
		}
		if len(out) > 0 {
			return out
		}
	}
	return nil
}

// Heading is a component's name and version, or its members' count.
func (c Component) Heading() string {
	switch {
	case c.Version != "":
		return c.Name + " " + c.Version
	case len(c.Packages) > 1:
		return c.Name + " (" + strconv.Itoa(len(c.Packages)) + " packages)"
	}
	return c.Name
}

// Notice is a component as plain text: its heading, licence, where it's
// from, its members, its note and its licence text.
func (c Component) Notice() string {
	var b strings.Builder
	b.WriteString(c.Heading() + "\n")
	b.WriteString("Licence: " + c.License + "\n")
	if c.URL != "" {
		b.WriteString(c.URL + "\n")
	}
	if len(c.Packages) > 1 {
		b.WriteString("Packages:")
		for _, p := range c.Packages {
			b.WriteString(" " + p.Name + "@" + p.Version)
		}
		b.WriteString("\n")
	}
	if c.Note != "" {
		b.WriteString(c.Note + "\n")
	}
	b.WriteString("\n" + c.Text + "\n")
	return b.String()
}
